const root = process.env.ZODY_CUA_PLUGIN_ROOT ?? process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
const { join } = await import('node:path');
const { pathToFileURL } = await import('node:url');
const { setupComputerUseRuntime } = await import(pathToFileURL(join(root, 'scripts', 'computer-use-client.mjs')).href);
await setupComputerUseRuntime({ globals: globalThis });
const { readFile } = await import('node:fs/promises');
const f = JSON.parse(await readFile('{{e2eRuntimeRoot}}/cua-r1/manifest.json', 'utf8'));
const ref = { pid: f.pid, window_id: f.targetWindow };

const knownCodes = new Set(['permission_denied','not_authorized','screen_locked','broker_unavailable','element_unavailable','structured_state_unavailable','action_unavailable','timeout','invalid_request','stale_state','internal']);
const safe = (v) => {
  let o = v;
  if (typeof v === 'string') { try { o = JSON.parse(v); } catch {} }
  const code = o && typeof o === 'object' && typeof o.code === 'string' && knownCodes.has(o.code.toLowerCase()) ? o.code.toLowerCase() : null;
  return {type:Array.isArray(o)?'array':o===null?'null':typeof o, code};
};
const selectApps = (apps) => Array.isArray(apps) ? apps.filter(a => a?.pid === f.pid).map(a => ({pid:a.pid})) : [];
const selectWindows = (windows) => Array.isArray(windows) ? windows.filter(w => w?.pid === f.pid && (w.window_id === f.targetWindow || w.window_id === f.siblingWindow)).map(w => ({pid:w.pid,window_id:w.window_id,text_preview_is_null:w.text_preview === null,onscreen:w.onscreen === true,main_type:typeof w.main,focused_type:typeof w.focused,subrole_present:typeof w.subrole === 'string'})) : [];
const report = (d) => nodeRepl.write('R1_DIAG:'+JSON.stringify(d));
const invoke = async (caseName, fn) => { try { return await fn(); } catch (error) { const diag = {case:caseName, result:safe(error)}; report(diag); throw new Error('R1_SDK_EXCEPTION R1_DIAG:'+JSON.stringify(diag)); } };
const state = await agent.computerUse.computer.get_app_state({app_ref:ref,disable_diffing:true});
if (typeof state !== 'string' || !state.startsWith('AX window state') || !state.includes(f.targetMarker) || state.includes(f.siblingMarker)) throw new Error('R1_FULL_FAILED');
nodeRepl.write(state); nodeRepl.write('R1_FULL_OK');

